#!/usr/bin/env bash
# Some portions generated by Codex. Independent nine-class production families, no current target/classes fallback.
set -euo pipefail
cd "$(dirname "$0")/../../.."
D=experiments/threadlocal-audit/ordered-values
exec 9>experiments/overlay/native-benchmark.lock
flock 9
for arm in base stack; do
 cp=$(cat experiments/threadlocal-audit/serializer-workbench/cp-base.txt)
 [[ $arm == stack ]] && cp=$(cat experiments/threadlocal-audit/serializer-workbench/cp-both.txt)
 ../toolchain/jdk-25.0.5+8/bin/javac --release 25 -g -proc:none -sourcepath "$D/empty-sourcepath" -cp "$cp" -d "$D/$arm-candidate-layer" "$D/$arm-candidate-source/"*.java > "$D/$arm-candidate-javac.log" 2>&1
 cp="$PWD/.m2_repo/org/springframework/spring-test/7.0.10/spring-test-7.0.10.jar:$PWD/$D/$arm-candidate-layer:$PWD/tools/workbench/target/test-classes:$cp:$(cat experiments/threadlocal-audit/read-depth/cp_a.txt)"
 printf '%s\n' "$cp" > "$D/isolated-$arm.classpath.txt"
 tests=(org.eclipse.rdf4j.workbench.util.WorkbenchOrderedValuesTest org.eclipse.rdf4j.workbench.util.WorkbenchPageResultWriterTest org.eclipse.rdf4j.workbench.util.QueryEvaluatorTest org.eclipse.rdf4j.workbench.util.QueryBatchEvaluationTest)
 if [[ $arm == stack ]]; then
  tests+=(org.eclipse.rdf4j.workbench.util.WorkbenchCompactTokenWriterTest)
 else
  for method in packedTermsMatchGenericJsonBytesIncludingEscapingAndNestedTriples batchesAndExplicitFlushKeepExactRecordBoundaries capAndOversizedRowsRetainExactBytesAndOrder laterTermFailureStillOccursBeforeAnyRowBytes surrogateSerializationMatchesGenericBytesAndFailureCleanup depthFailureKeepsGenericPartialBytesAndDiagnostics; do
   tests+=("org.eclipse.rdf4j.workbench.util.WorkbenchCompactTokenWriterTest#$method")
  done
 fi
 expected=126; [[ $arm == stack ]] && expected=128
 ../toolchain/jdk-25.0.5+8/bin/java -Dexpected.tests=$expected -ea -javaagent:$PWD/.m2_repo/org/mockito/mockito-core/5.24.0/mockito-core-5.24.0.jar --source 25 -cp "$cp" "$D/FocusedLauncher.java" "${tests[@]}" > "$D/isolated-$arm.log" 2>&1
 echo "isolated_arm=$arm exit=0"
done
